import { z } from "zod";
import {
  CraftStart,
  FieldHarvest,
  FieldPlant,
  GatherStart,
  MoveTo,
  StorehouseTransfer,
  Turn,
  VillagerAssign,
} from "./messages.ts";

/**
 * One player action sent to POST /game/actions (Phase 1, ADR 0002).
 * `requestId` is generated by the client per action; resending the same id
 * returns the original result instead of applying the action twice.
 * Add new action types as members of this union.
 */
export const ActionRequest = z.discriminatedUnion("type", [
  z.strictObject({ requestId: z.uuid(), type: z.literal("move.to"), payload: MoveTo }),
  z.strictObject({ requestId: z.uuid(), type: z.literal("turn"), payload: Turn }),
  z.strictObject({ requestId: z.uuid(), type: z.literal("gather.start"), payload: GatherStart }),
  z.strictObject({ requestId: z.uuid(), type: z.literal("craft.start"), payload: CraftStart }),
  z.strictObject({ requestId: z.uuid(), type: z.literal("field.harvest"), payload: FieldHarvest }),
  z.strictObject({ requestId: z.uuid(), type: z.literal("field.plant"), payload: FieldPlant }),
  z.strictObject({
    requestId: z.uuid(),
    type: z.literal("villager.assign"),
    payload: VillagerAssign,
  }),
  z.strictObject({
    requestId: z.uuid(),
    type: z.literal("storehouse.store"),
    payload: StorehouseTransfer,
  }),
  z.strictObject({
    requestId: z.uuid(),
    type: z.literal("storehouse.take"),
    payload: StorehouseTransfer,
  }),
]);
export type ActionRequest = z.infer<typeof ActionRequest>;

/**
 * An action without its requestId: what game rules receive. Distributes over the
 * union (a plain Omit would merge the members and lose which payload goes with which type).
 */
export type GameAction = ActionRequest extends infer Request
  ? Request extends ActionRequest
    ? Omit<Request, "requestId">
    : never
  : never;
export type GameActionType = GameAction["type"];
